2.17 Laboratorio interactivo: preparar datos
Explora valores faltantes, imputación y estandarización.
#| '!! shinylive warning !!': |
#|   shinylive does not work in self-contained HTML documents.
#|   Please set `embed-resources: false` in your metadata.
#| standalone: true
#| viewerHeight: 720
#| components: [viewer]

library(shiny)

ui &lt;- fluidPage(
  titlePanel("Preparación interactiva de datos"),
  sidebarLayout(
    sidebarPanel(
      sliderInput("faltantes", "Porcentaje de valores faltantes",
                  0, 40, 15, step = 5),
      selectInput("imputacion", "Método de imputación",
                  choices = c("Media" = "media", "Mediana" = "mediana")),
      checkboxInput("escalar", "Estandarizar variables", TRUE),
      numericInput("semilla", "Semilla", 123, min = 1)
    ),
    mainPanel(
      h4("Datos con valores faltantes"),
      tableOutput("antes"),
      h4("Datos preparados"),
      tableOutput("despues"),
      tableOutput("resumen")
    )
  )
)

server &lt;- function(input, output, session) {
  datos &lt;- reactive({
    set.seed(input$semilla)
    d &lt;- data.frame(
      temperatura = round(rnorm(12, 25, 4), 1),
      humedad = round(rnorm(12, 55, 12), 1),
      contaminacion = round(rnorm(12, 40, 10), 1)
    )
    n_na &lt;- round(length(as.matrix(d)) * input$faltantes / 100)
    if (n_na &gt; 0) {
      m &lt;- as.matrix(d)
      m[sample(seq_len(length(m)), n_na)] &lt;- NA
      d &lt;- as.data.frame(m)
    }
    d
  })

  preparados &lt;- reactive({
    d &lt;- datos()
    for (j in seq_along(d)) {
      valor &lt;- if (input$imputacion == "media") {
        mean(d[[j]], na.rm = TRUE)
      } else {
        median(d[[j]], na.rm = TRUE)
      }
      d[[j]][is.na(d[[j]])] &lt;- valor
    }
    if (input$escalar) d &lt;- as.data.frame(scale(d))
    d
  })

  output$antes &lt;- renderTable(datos(), digits = 2)
  output$despues &lt;- renderTable(preparados(), digits = 3)

  output$resumen &lt;- renderTable({
    data.frame(
      Etapa = c("Antes", "Después"),
      Valores_faltantes = c(sum(is.na(datos())), sum(is.na(preparados()))),
      Media_variable_1 = round(c(mean(datos()[[1]], na.rm = TRUE),
                                 mean(preparados()[[1]])), 3),
      Desviacion_variable_1 = round(c(sd(datos()[[1]], na.rm = TRUE),
                                      sd(preparados()[[1]])), 3)
    )
  })
}

shinyApp(ui, server)

