4.21 Supuestos principales
La interpretación inferencial tradicional de la regresión lineal se apoya en varios supuestos:

relación aproximadamente lineal;
errores independientes;
varianza aproximadamente constante;
ausencia de colinealidad extrema;
normalidad aproximada de los errores cuando se construyen pruebas e intervalos.

Los supuestos deben analizarse mediante gráficas, conocimiento del problema y medidas diagnósticas; no deben tratarse como una lista mecánica.

4.23 Laboratorio interactivo: regresión lineal
Modifica el intercepto, la pendiente y el nivel de ruido para observar cómo cambia la nube de puntos y la recta de regresión.
#| '!! shinylive warning !!': |
#|   shinylive does not work in self-contained HTML documents.
#|   Please set `embed-resources: false` in your metadata.
#| standalone: true
#| viewerHeight: 700
#| components: [viewer]

library(shiny)

ui &lt;- fluidPage(
  titlePanel("Laboratorio de regresión lineal"),

  sidebarLayout(
    sidebarPanel(
      sliderInput("b0", "Intercepto", -10, 10, 2, 0.5),
      sliderInput("b1", "Pendiente", -5, 5, 1.5, 0.1),
      sliderInput("ruido", "Desviación del ruido", 0, 8, 2, 0.25),
      sliderInput("n", "Número de observaciones", 20, 200, 60, 10),
      numericInput("semilla", "Semilla", 123, min = 1)
    ),

    mainPanel(
      plotOutput("grafica", height = "450px"),
      verbatimTextOutput("modelo"),
      textOutput("interpretacion")
    )
  )
)

server &lt;- function(input, output, session) {

  datos &lt;- reactive({
    set.seed(input$semilla)
    x &lt;- runif(input$n, 0, 10)
    y &lt;- input$b0 + input$b1 * x +
      rnorm(input$n, 0, input$ruido)
    data.frame(x = x, y = y)
  })

  ajuste &lt;- reactive({
    lm(y ~ x, data = datos())
  })

  output$grafica &lt;- renderPlot({
    d &lt;- datos()

    plot(
      d$x, d$y,
      pch = 19,
      xlab = "Variable x",
      ylab = "Variable y",
      main = "Datos simulados y recta estimada"
    )

    abline(ajuste(), lwd = 3)
    abline(
      a = input$b0,
      b = input$b1,
      lty = 2,
      lwd = 2
    )

    legend(
      "topleft",
      legend = c("Recta estimada", "Recta verdadera"),
      lty = c(1, 2),
      lwd = c(3, 2),
      bty = "n"
    )
  })

  output$modelo &lt;- renderPrint({
    coeficientes &lt;- coef(ajuste())
    r2 &lt;- summary(ajuste())$r.squared

    cat("Modelo estimado:\n")
    cat(
      "y =",
      round(coeficientes[1], 3),
      "+",
      round(coeficientes[2], 3),
      "x\n\n"
    )
    cat("R² =", round(r2, 4))
  })

  output$interpretacion &lt;- renderText({
    if (input$ruido &lt; 1) {
      "Con poco ruido, la recta estimada suele aproximarse mucho a la relación verdadera."
    } else if (input$ruido &lt; 4) {
      "El ruido genera dispersión y reduce la precisión del ajuste."
    } else {
      "Con ruido alto, la relación es más difícil de identificar y el R² suele disminuir."
    }
  })
}

shinyApp(ui, server)

5.11 Laboratorio interactivo: regresión logística
Explora cómo el intercepto, la pendiente y el umbral cambian la probabilidad estimada y la clasificación final.
#| '!! shinylive warning !!': |
#|   shinylive does not work in self-contained HTML documents.
#|   Please set `embed-resources: false` in your metadata.
#| standalone: true
#| viewerHeight: 720
#| components: [viewer]

library(shiny)

sigmoide &lt;- function(z) {
  1 / (1 + exp(-z))
}

ui &lt;- fluidPage(
  titlePanel("Laboratorio de regresión logística"),

  sidebarLayout(
    sidebarPanel(
      sliderInput("b0", "Intercepto", -10, 10, -3, 0.25),
      sliderInput("b1", "Pendiente", -5, 5, 1.2, 0.1),
      sliderInput("umbral", "Umbral de clasificación", 0.05, 0.95, 0.5, 0.05),
      sliderInput("xnew", "Valor nuevo de x", -5, 10, 2.5, 0.1)
    ),

    mainPanel(
      plotOutput("curva", height = "440px"),
      verbatimTextOutput("resultado"),
      textOutput("interpretacion")
    )
  )
)

server &lt;- function(input, output, session) {

  prob_nueva &lt;- reactive({
    sigmoide(input$b0 + input$b1 * input$xnew)
  })

  output$curva &lt;- renderPlot({
    x &lt;- seq(-5, 10, length.out = 400)
    p &lt;- sigmoide(input$b0 + input$b1 * x)

    plot(
      x, p,
      type = "l",
      lwd = 3,
      ylim = c(0, 1),
      xlab = "Variable x",
      ylab = "Probabilidad estimada",
      main = "Curva logística y umbral"
    )

    abline(h = input$umbral, lty = 2)
    abline(v = input$xnew, lty = 3)

    points(
      input$xnew,
      prob_nueva(),
      pch = 19,
      cex = 1.8
    )

    text(
      input$xnew,
      prob_nueva(),
      labels = paste0("  p = ", round(prob_nueva(), 3)),
      pos = 4
    )
  })

  output$resultado &lt;- renderPrint({
    clase &lt;- ifelse(
      prob_nueva() &gt;= input$umbral,
      1,
      0
    )

    cat("Logit =", round(input$b0 + input$b1 * input$xnew, 4), "\n")
    cat("Probabilidad =", round(prob_nueva(), 4), "\n")
    cat("Umbral =", input$umbral, "\n")
    cat("Clase predicha =", clase)
  })

  output$interpretacion &lt;- renderText({
    if (prob_nueva() &gt;= input$umbral) {
      "La probabilidad supera el umbral, por lo que la observación se asigna a la clase 1."
    } else {
      "La probabilidad no alcanza el umbral, por lo que la observación se asigna a la clase 0."
    }
  })
}

shinyApp(ui, server)

