server &lt;- function(input, output, session) {
  posterior &lt;- reactive({
    p1 &lt;- input$prior
    p0 &lt;- 1 - p1
    if (input$observada == "si") {
      l1 &lt;- input$e1
      l0 &lt;- input$e0
    } else {
      l1 &lt;- 1 - input$e1
      l0 &lt;- 1 - input$e0
    }
    num1 &lt;- p1 * l1
    num0 &lt;- p0 * l0
    evidencia &lt;- num1 + num0
    c(Clase_0 = num0 / evidencia, Clase_1 = num1 / evidencia)
  })

  output$calculo &lt;- renderTable({
    p &lt;- posterior()
    data.frame(
      Clase = names(p),
      Probabilidad_posterior = round(as.numeric(p), 4)
    )
  })

  output$grafica &lt;- renderPlot({
    p &lt;- posterior()
    barplot(p, ylim = c(0, 1),
            ylab = "Probabilidad posterior",
            main = "Resultado de Naive Bayes")
    abline(h = 0.5, lty = 2)
  })

  output$decision &lt;- renderText({
    p &lt;- posterior()
    paste("Clase predicha:",
          ifelse(p["Clase_1"] &gt;= p["Clase_0"], "Clase 1", "Clase 0"))
  })
}

shinyApp(ui, server)

